import Foundation
import AppKit

/// What a process actually is, in one line.
///
/// Activity Monitor tells you `mds_stores` is using 8% CPU and leaves you to know
/// what `mds_stores` is. This answers that, from two sources:
///
/// * the bundle on disk, for anything running out of an `.app` — its display name
///   is what you already call the app, which `com.apple.WebKit.WebContent` is not;
/// * a curated table for the system daemons, which have no bundle and are exactly
///   the names that are unrecognisable.
///
/// Everything is resolved off the main thread and cached by executable path, so the
/// table never pays for it while scrolling. A row asked about before its answer is
/// ready shows nothing and picks it up on the next refresh rather than blocking —
/// reading a bundle means touching the disk, and the process list is re-rendered far
/// too often to do that inline.
final class ProcessDescriptions: @unchecked Sendable {
    static let shared = ProcessDescriptions()

    private let lock = NSLock()
    private var cache: [String: String] = [:]
    private var inFlight: Set<String> = []
    private let queue = DispatchQueue(label: "com.ivogundlach.vitals.descriptions",
                                      qos: .utility)

    /// Cache key. Two processes from the same executable have the same description,
    /// and a PID would make the cache useless — it changes every launch.
    private func key(_ row: ProcRow) -> String {
        row.counters.path.isEmpty ? "name:\(row.name)" : row.counters.path
    }

    func describe(_ row: ProcRow) -> String {
        let cacheKey = key(row)

        lock.lock()
        if let hit = cache[cacheKey] {
            lock.unlock()
            return hit
        }
        // The curated answer needs no disk, so it can be given immediately and
        // cached without a round trip.
        if let known = Self.systemDaemons[row.name] {
            cache[cacheKey] = known
            lock.unlock()
            return known
        }
        let alreadyRunning = inFlight.contains(cacheKey)
        if !alreadyRunning { inFlight.insert(cacheKey) }
        lock.unlock()

        if !alreadyRunning {
            let path = row.counters.path
            let name = row.name
            queue.async { [weak self] in
                let resolved = Self.resolve(path: path, name: name)
                guard let self else { return }
                self.lock.lock()
                self.cache[cacheKey] = resolved
                self.inFlight.remove(cacheKey)
                self.lock.unlock()
            }
        }
        return ""
    }

    /// Walks up from the executable to the `.app` that contains it, if any.
    ///
    /// A helper's own bundle is the wrong answer — `Claude Helper (Renderer)` lives
    /// in `Claude.app/Contents/Frameworks/…`, and what you want to know is that it
    /// belongs to Claude. So the *outermost* enclosing app wins, and the helper's
    /// own role is kept as a qualifier.
    private static func resolve(path: String, name: String) -> String {
        guard !path.isEmpty else { return "" }

        var outermost: URL?
        var url = URL(fileURLWithPath: path)
        while url.pathComponents.count > 1 {
            url = url.deletingLastPathComponent()
            if url.pathExtension == "app" { outermost = url }
        }

        guard let appURL = outermost,
              let bundle = Bundle(url: appURL) else {
            return describeUnbundled(path: path, name: name)
        }

        let info = bundle.infoDictionary ?? [:]
        let display = (info["CFBundleDisplayName"] as? String)
            ?? (info["CFBundleName"] as? String)
            ?? appURL.deletingPathExtension().lastPathComponent

        let helperRole = appURL.deletingPathExtension().lastPathComponent
        if helperRole != name && !name.hasPrefix(display) {
            return "\(display) — \(name)"
        }
        // An app whose bundle name is its process name has nothing to add: repeating
        // "Vitals" beside `Vitals` costs a column's width and says nothing. Blank is
        // the honest answer — the process name already was the description.
        return display == name ? "" : display
    }

    /// No bundle: say where it came from, which is the next most useful fact.
    private static func describeUnbundled(path: String, name: String) -> String {
        if path.hasPrefix("/usr/libexec/") || path.hasPrefix("/System/Library/") {
            return "macOS system service"
        }
        if path.hasPrefix("/usr/sbin/") || path.hasPrefix("/sbin/") {
            return "System daemon"
        }
        if path.hasPrefix("/opt/homebrew/") || path.hasPrefix("/usr/local/") {
            return "Homebrew or locally installed tool"
        }
        if path.hasPrefix("/usr/bin/") { return "Command-line tool" }
        if path.contains("/Library/LaunchAgents/") { return "Login item or launch agent" }
        return ""
    }

    /// The daemons worth naming: the ones that show up near the top of the table and
    /// look alarming until you know what they are.
    ///
    /// Built from pairs rather than written as a dictionary literal on purpose. A
    /// duplicate key in a literal this long is a runtime trap, and it fires the first
    /// time the table is touched — which is mid-scroll, in a cell factory. A cosmetic
    /// lookup should not be able to take the app down, so a repeat keeps the first
    /// wording instead.
    private static let systemDaemons: [String: String] =
        Dictionary(systemDaemonPairs, uniquingKeysWith: { first, _ in first })

